import { describe, expect, it } from 'vitest'
import { parseAtom, type Entry } from './atom'
import { keysURL, signingInput, verify, type KeyDoc } from './sign'
// Generated by a real amfeed (Go), so these tests check both implementations agree.
import feedXML from './__fixtures__/feed.atom?raw'
import keysJSON from './__fixtures__/keys.json'

const keys = keysJSON as KeyDoc

function testEntry(): Entry {
  return {
    id: 'tag:example.com,2026-10:post-1',
    title: '',
    summary: '',
    published: '2026-10-21T12:00:00Z',
    updated: '2026-10-21T12:00:00Z',
    author: { name: 'Ex', uri: 'https://example.com/' },
    content: { type: 'html', body: '<p>a\\b</p>\nline2\r' },
    links: [
      { rel: 'alternate', href: 'https://example.com/posts/1', type: '' },
      { rel: 'enclosure', href: 'https://example.com/a.jpg', type: 'image/jpeg' },
      { rel: 'enclosure', href: 'https://example.com/b.jpg', type: 'image/jpeg' },
    ],
    inReplyTo: { ref: 'tag:other.example,2026-10:post-9', href: 'https://other.example/posts/9' },
    verb: '',
    signature: null,
  }
}

describe('signingInput', () => {
  // Same golden value as TestInput in internal/sign/sign_test.go.
  it('matches the Go implementation', () => {
    expect(signingInput(testEntry())).toBe(
      [
        'id: tag:example.com,2026-10:post-1',
        'author: https://example.com/',
        'published: 2026-10-21T12:00:00Z',
        'updated: 2026-10-21T12:00:00Z',
        'in-reply-to: tag:other.example,2026-10:post-9',
        'verb: ',
        'title: ',
        'summary: ',
        'content-type: html',
        'content: <p>a\\\\b</p>\\nline2\\r',
        'enclosure: https://example.com/a.jpg',
        'enclosure: https://example.com/b.jpg',
      ].join('\n'),
    )
  })

  it('rejects xhtml content and missing author', () => {
    expect(() => signingInput({ ...testEntry(), content: { type: 'xhtml', body: '' } })).toThrow()
    expect(() => signingInput({ ...testEntry(), author: null })).toThrow()
  })
})

describe('verify against amfeed output', () => {
  const feed = parseAtom(feedXML)

  it('parses all entries', () => {
    expect(feed.entries).toHaveLength(5)
    const bodies = feed.entries.map((e) => e.content?.body)
    expect(bodies).toContain('line one\r\nline two\\with backslash\n\n  indented')
    expect(bodies).toContain('<p>HTML <em>content</em></p>')
    expect(feed.entries.find((e) => e.inReplyTo)?.inReplyTo?.ref).toMatch(/:post-1$/)
  })

  it('verifies every entry', async () => {
    for (const e of feed.entries) {
      await expect(verify(e, keys), e.id).resolves.toBeUndefined()
    }
  })

  it('rejects tampered content', async () => {
    const e = structuredClone(feed.entries[1])
    e.content!.body += '!'
    await expect(verify(e, keys)).rejects.toThrow('signature does not match')
  })

  it('accepts changed links, which are not signed', async () => {
    const e = structuredClone(feed.entries[1])
    e.links = [{ rel: 'alternate', href: 'https://agg.example/posts/abc', type: '' }]
    await expect(verify(e, keys)).resolves.toBeUndefined()
  })
})

describe('keysURL', () => {
  it('resolves against the author uri', () => {
    expect(keysURL('https://miki.one/')).toBe('https://miki.one/.well-known/atomic-keys')
    expect(keysURL('https://miki.one')).toBe('https://miki.one/.well-known/atomic-keys')
    expect(keysURL('http://localhost:8100/')).toBe('http://localhost:8100/.well-known/atomic-keys')
  })
})
